import type { TraceData, TraceSpan } from '../types/tracing';

/**
 * Shared utilities for trajectory assertions.
 *
 * A "trajectory" is the normalized sequence of execution steps an agent took,
 * derived from distributed-tracing spans (tool calls, command executions,
 * searches, reasoning steps, etc.).
 */

export type TrajectoryStepType = 'tool' | 'command' | 'reasoning' | 'search' | 'span';

export interface TrajectoryStep {
  /** Normalized step type. */
  type: TrajectoryStepType;
  /** Human/machine friendly name for the step (e.g. the tool name). */
  name: string;
  /** The original span name this step was derived from. */
  spanName: string;
  /** Alternative names this step can be matched by (e.g. command's first word). */
  aliases: string[];
}

/** Span names beginning with this pattern are treated as reasoning steps. */
const REASONING_PATTERN = /^reasoning/i;

/** Heuristic terms that indicate a span with a query attribute is a search. */
const SEARCH_LIKE_PATTERN = /search|retriev|lookup|semantic/i;

function asString(value: unknown): string | undefined {
  return typeof value === 'string' && value.length > 0 ? value : undefined;
}

/**
 * Determine whether a span name looks like a search operation (as opposed to,
 * for example, a SQL query span which also carries a `query` attribute).
 */
function isSearchLike(spanName: string): boolean {
  return SEARCH_LIKE_PATTERN.test(spanName);
}

/**
 * Classify a single span into a normalized trajectory step.
 */
function classifySpan(span: TraceSpan): TrajectoryStep {
  const attributes = span.attributes || {};
  const spanName = span.name;

  // 1. Generic tool call spans (OTEL-style `tool.name` attribute).
  const toolName = asString(attributes['tool.name']);
  if (toolName) {
    return { type: 'tool', name: toolName, spanName, aliases: [] };
  }

  // 2. MCP tool call spans. The original span name (e.g. "mcp inventory/search_inventory")
  //    is retained as an alias so the step can be matched by either name.
  const mcpTool = asString(attributes['codex.mcp.tool']);
  if (mcpTool) {
    return { type: 'tool', name: mcpTool, spanName, aliases: [spanName] };
  }

  // 3. Command execution spans. The full command is the name; its first word
  //    (e.g. "ls" for "ls -la") is retained as an alias.
  const command = asString(attributes['codex.command']);
  if (command) {
    const firstWord = command.trim().split(/\s+/)[0] || command;
    return { type: 'command', name: command, spanName, aliases: [firstWord] };
  }

  // 4. Reasoning spans, identified by their span name.
  if (REASONING_PATTERN.test(spanName)) {
    return { type: 'reasoning', name: spanName, spanName, aliases: [] };
  }

  // 5. Search spans: a span carrying a query attribute whose name looks search-like.
  //    A query attribute on a non-search span (e.g. a SQL query) falls through to a
  //    generic span below.
  const query = asString(attributes['query']) ?? asString(attributes['codex.search.query']);
  if (query !== undefined && isSearchLike(spanName)) {
    return { type: 'search', name: query, spanName, aliases: [] };
  }

  // 6. Fallback: a generic span keyed by its name.
  return { type: 'span', name: spanName, spanName, aliases: [] };
}

/**
 * Accept a TraceData object and return an array of normalized trajectory steps,
 * ordered chronologically by span start time.
 */
export function extractTrajectorySteps(trace: TraceData): TrajectoryStep[] {
  const spans = trace?.spans ?? [];
  const ordered = [...spans].sort((a, b) => (a.startTime ?? 0) - (b.startTime ?? 0));
  return ordered.map(classifySpan);
}

interface CompactedStep {
  index: number;
  type: TrajectoryStepType;
  name: string;
  spanName: string;
  collapsedCount: number;
}

interface SummaryStepEntry {
  index: number;
  type: TrajectoryStepType;
  name: string;
  spanName?: string;
  collapsedCount?: number;
}

/** Maximum number of entries retained in the summarized steps array. */
const MAX_SUMMARY_STEPS = 25;
/** Number of head/tail entries kept when truncating. */
const SUMMARY_HEAD_TAIL = 12;

function toSummaryEntry(step: CompactedStep): SummaryStepEntry {
  const entry: SummaryStepEntry = {
    index: step.index,
    type: step.type,
    name: step.name,
  };
  if (step.spanName !== step.name) {
    entry.spanName = step.spanName;
  }
  if (step.collapsedCount > 1) {
    entry.collapsedCount = step.collapsedCount;
  }
  return entry;
}

/**
 * Accept a TraceData object and return a pretty-printed JSON summary of the
 * trajectory suitable for handing to an LLM judge.
 */
export function summarizeTrajectoryForJudge(trace: TraceData): string {
  const steps = extractTrajectorySteps(trace);
  const stepCount = steps.length;

  // Collapse consecutive identical steps.
  const compacted: CompactedStep[] = [];
  for (let i = 0; i < steps.length; i++) {
    const step = steps[i];
    const last = compacted[compacted.length - 1];
    if (
      last &&
      last.type === step.type &&
      last.name === step.name &&
      last.spanName === step.spanName
