  if (compactedStepCount > MAX_SUMMARY_STEPS - 1) {
    const head = compacted.slice(0, SUMMARY_HEAD_TAIL).map(toSummaryEntry);
    const tail = compacted.slice(compactedStepCount - SUMMARY_HEAD_TAIL).map(toSummaryEntry);
    const omittedCount = compactedStepCount - SUMMARY_HEAD_TAIL * 2;
    summarySteps = [...head, { omittedCount }, ...tail];
  } else {
    summarySteps = compacted.map(toSummaryEntry);
  }

  return JSON.stringify(
    {
      stepCount,
      compactedStepCount,
      steps: summarySteps,
    },
    null,
    2,
  );
}

