const DEFAULT_TRAJECTORY_GOAL_SUCCESS_PROMPT = JSON.stringify([
  {
    role: 'system',
    content:
      'You are evaluating whether an AI agent successfully achieved a specified goal, based on its execution trajectory and final output. Respond with a JSON object with this structure: {"reason": string, "pass": boolean, "score": number}. Set "pass" to true only if the agent achieved the goal, and "score" to a number between 0 and 1 reflecting how well the goal was achieved.',
  },
  {
    role: 'user',
    content:
      '<Goal>\n{{ goal }}\n</Goal>\n<Trajectory>\n{{ trajectory }}\n</Trajectory>\n<Output>\n{{ output }}\n</Output>',
  },
]);

/**
 * Grade whether an agent achieved a goal, given the goal, a summarized
 * trajectory, and the final output. The goal, trajectory, and output are
 * rendered as template variables into the grading rubric prompt.
 */
export async function matchesTrajectoryGoalSuccess(
  goal: string,
  trajectory: string,
  output: string,
  grading: GradingConfig | undefined,
  vars?: Record<string, unknown>,
  assertion?: Assertion,
  providerCallContext?: object,
): Promise<GradingResult> {
  if (!grading) {
    throw new Error('Cannot grade output without grading config');
  }

  const rubricPrompt = await loadRubricPrompt(
    grading.rubricPrompt,
    DEFAULT_TRAJECTORY_GOAL_SUCCESS_PROMPT,
  );

  // Actual argument values must override any caller-supplied vars of the same
  // name so callers cannot spoof the graded goal/trajectory/output.
  const templateVars = {
    ...(vars || {}),
    goal,
    trajectory,
    output,
  } as Record<string, VarValue>;

  const prompt = await renderLlmRubricPrompt(rubricPrompt, templateVars);

  const defaultProviders = await getDefaultProviders();
  const defaultProvider =
    defaultProviders.llmRubricProvider || defaultProviders.gradingJsonProvider;
  const finalProvider = await getAndCheckProvider(
    'text',
    grading.provider,
    defaultProvider,
    'trajectory:goal-success check',
  );

  const resp = await callProviderWithContext(
    finalProvider,
    prompt,
    'trajectory:goal-success',
    templateVars,
    providerCallContext as CallApiContextParams | undefined,
  );

  const buildResult = (pass: boolean, score: number, reason: string): GradingResult => ({
    pass,
    score,
    reason,
    assertion,
    tokensUsed: {
      total: resp.tokenUsage?.total || 0,
      prompt: resp.tokenUsage?.prompt || 0,
      completion: resp.tokenUsage?.completion || 0,
      cached: 0,
      numRequests: 0,
      completionDetails: {
        reasoning: 0,
        acceptedPrediction: 0,
        rejectedPrediction: 0,
      },
    },
    metadata: {
      renderedGradingPrompt: prompt,
    },
  });

  if (resp.error || !resp.output) {
    return buildResult(false, 0, resp.error || 'No output from grading provider');
  }

  let parsed: Partial<GradingResult> | undefined;
  if (typeof resp.output === 'object') {
    parsed = resp.output as Partial<GradingResult>;
  } else {
    try {
      const jsonObjects = extractJsonObjects(String(resp.output));
      parsed = jsonObjects[0] as Partial<GradingResult> | undefined;
    } catch {
      parsed = undefined;
    }
    if (!parsed) {
      return buildResult(
        false,
        0,
        `Could not extract JSON from trajectory:goal-success response: ${resp.output}`,
      );
    }
  }

  let pass: boolean = (parsed.pass as boolean) ?? true;
  if (typeof pass !== 'boolean') {
    pass = /^(true|yes|pass|y)$/i.test(String(pass));
  }

  let score = parsed.score;
  if (typeof score !== 'number') {
    score = Number.isFinite(Number(score)) ? Number(score) : Number(pass);
  }

  const threshold =
    typeof assertion?.threshold === 'string' ? Number(assertion.threshold) : assertion?.threshold;
  if (typeof threshold === 'number' && Number.isFinite(threshold) && score < threshold) {
    pass = false;
  }

  const reason = parsed.reason || (pass ? 'Goal achieved' : 'Goal not achieved');
